<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';msp2RequireAccess();
$tipo=strtoupper(trim((string)($_GET['tipo']??'')));$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$row=null;
if($tipo==='RECEPCION'&&$id){$stmt=$conn->prepare("SELECT r.id_recepcion_garantia id_operacion,r.fecha_recepcion fecha,r.monto_recibido monto,r.medio_recepcion medio,r.referencia,r.banco_emisor,r.numero_cheque,r.observaciones,g.id_garantia,g.id_contrato_arriendo,a.nombre_locatario beneficiario,a.rut,l.cdo_local FROM dbo.msp_garantia_recepciones r JOIN dbo.msp_garantias g ON g.id_garantia=r.id_garantia JOIN dbo.msp_contratos_arriendo c ON c.id_contrato_arriendo=g.id_contrato_arriendo JOIN dbo.msp_arrendatarios a ON a.id_arrendatario=c.id_arrendatario JOIN dbo.msp_locales l ON l.id_local=g.id_local WHERE r.id_recepcion_garantia=:id");$stmt->execute([':id'=>(int)$id]);$row=$stmt->fetch();$titulo='Comprobante de recepción de garantía';}
elseif($tipo==='DEVOLUCION'&&$id){$stmt=$conn->prepare("SELECT d.id_devolucion_garantia id_operacion,d.fecha_devolucion fecha,d.monto_devolucion monto,d.medio_devolucion medio,COALESCE(d.referencia_transferencia,d.numero_cheque) referencia,d.banco_destino banco_emisor,d.numero_cheque,d.observaciones,g.id_garantia,g.id_contrato_arriendo,d.beneficiario,d.rut_beneficiario rut,l.cdo_local FROM dbo.msp_garantia_devoluciones d JOIN dbo.msp_garantias g ON g.id_garantia=d.id_garantia JOIN dbo.msp_locales l ON l.id_local=g.id_local WHERE d.id_devolucion_garantia=:id");$stmt->execute([':id'=>(int)$id]);$row=$stmt->fetch();$titulo='Comprobante de devolución de garantía';}
if(!$row){http_response_code(404);exit('Comprobante no encontrado.');}$download=($_GET['download']??'')==='1';if($download){header('Content-Disposition: attachment; filename="comprobante_'.strtolower($tipo).'_'.(int)$id.'.html"');}header('Content-Type: text/html; charset=UTF-8');
?><!doctype html><html lang="es"><head><meta charset="utf-8"><title><?php echo msp2Escape($titulo);?></title><style>body{font-family:Arial,sans-serif;color:#172033;margin:40px}.sheet{max-width:780px;margin:auto;border:1px solid #ccd3dd;padding:34px}.head{display:flex;justify-content:space-between;border-bottom:2px solid #183b66;padding-bottom:16px}.title{font-size:23px;font-weight:bold}.num{color:#596579}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:25px 0}.item{border-bottom:1px solid #ddd;padding:8px 0}.label{font-size:12px;color:#667085;text-transform:uppercase}.value{font-size:16px;margin-top:4px}.amount{font-size:28px;font-weight:bold;color:#183b66}.sign{display:flex;gap:70px;margin-top:70px}.line{border-top:1px solid #333;width:260px;text-align:center;padding-top:7px}@media print{.actions{display:none}body{margin:0}.sheet{border:0}}</style></head><body><div class="actions" style="max-width:780px;margin:0 auto 15px"><button onclick="window.print()">Imprimir / Guardar PDF</button> <a href="?tipo=<?php echo urlencode($tipo);?>&id=<?php echo (int)$id;?>&download=1">Descargar HTML</a></div><div class="sheet"><div class="head"><div><div class="title"><?php echo msp2Escape($titulo);?></div><div class="num">MSP · Garantía #<?php echo (int)$row['id_garantia'];?> · Contrato #<?php echo (int)$row['id_contrato_arriendo'];?></div></div><div class="num">N.º <?php echo (int)$row['id_operacion'];?></div></div><div class="grid"><div class="item"><div class="label">Fecha</div><div class="value"><?php echo msp2Escape(date('d-m-Y',strtotime((string)$row['fecha'])));?></div></div><div class="item"><div class="label">Local</div><div class="value"><?php echo msp2Escape((string)$row['cdo_local']);?></div></div><div class="item"><div class="label"><?php echo $tipo==='RECEPCION'?'Arrendatario':'Beneficiario';?></div><div class="value"><?php echo msp2Escape((string)$row['beneficiario']);?></div></div><div class="item"><div class="label">RUT</div><div class="value"><?php echo msp2Escape((string)($row['rut']??'-'));?></div></div><div class="item"><div class="label">Medio</div><div class="value"><?php echo msp2Escape((string)$row['medio']);?></div></div><div class="item"><div class="label">Referencia / cheque</div><div class="value"><?php echo msp2Escape((string)($row['referencia']??'-'));?></div></div></div><div class="item"><div class="label">Monto</div><div class="amount">$ <?php echo number_format((float)$row['monto'],2,',','.');?></div></div><div class="item"><div class="label">Observaciones</div><div class="value"><?php echo msp2Escape((string)($row['observaciones']??'-'));?></div></div><div class="sign"><div class="line">MSP / Responsable</div><div class="line"><?php echo $tipo==='RECEPCION'?'Entregado por':'Recibido por';?></div></div></div></body></html>
